{"version":3,"sources":["dark.scss","_variables.scss","dark.css"],"names":[],"mappings":"AAGA;EACC,yBCaY;ACfb;AFIC;EACC,wCAAA;AEFF;AFME;EACC,cCgCK;ACpCR;AFOE;EACC,gCAAA;AELH;AFSC;EACC,yBCuBM;AC9BR;AFUC;;;;;;;EAOC,cCaM;ACrBR;AFUC;EACC,cCjBW;ACSb;AFYE;EACC,iBAAA;AEVH;AFcG;EACC,aAAA;AEZJ;AFiBC;;EAEC,qBCjCW;ACkBb","file":"dark.css","sourcesContent":["// compiled standalone as well as appended to style.scss, so it needs the palette\n@import \"variables\";\n\n.dark {\n\tbackground-color: $forest-800;\n\n\t.page-home .overlay {\n\t\tbackground-color: rgba($forest-900, 0.97);\n\t}\n\n\t.page-title {\n\t\th2 {\n\t\t\tcolor: $light;\n\t\t}\n\n\t\t.title-bg {\n\t\t\tcolor: rgba($moss, 0.06);\n\t\t}\n\t}\n\n\t.section-title h3::before {\n\t\tbackground-color: $light;\n\t}\n\n\th1,\n\th2,\n\th3,\n\th4,\n\th5,\n\th6,\n\t.about-author .author-desc p {\n\t\tcolor: $light;\n\t}\n\t.switcher-body h4 {\n\t\tcolor: $forest-800;\n\t}\n\n\t.service-hex {\n\t\t.st0 {\n\t\t\tfill: transparent;\n\t\t}\n\n\t\t&:hover {\n\t\t\t.st0 {\n\t\t\t\tfill: $light;\n\t\t\t}\n\t\t}\n\t}\n\n\t.testimonials .text,\n\t.btn-border {\n\t\tborder-color: $forest-700;\n\t}\n}","//\n// Typography\n//\n\n$font-stack: \"Libre Baskerville\", serif;\n$open-sans: \"Open Sans\", sans-serif;\n\n//\n// Palette — forest, gold and wood\n//\n// Three families do all the work: deep forest greens for structure, gold for\n// every accent and highlight, and wood browns for warmth underneath. Parchment\n// stands in for white so nothing on the site is ever a cold grey.\n//\n\n// Forest — panels, cards, hexagons, anything structural\n$forest-900: #0b1410; // deepest wells and overlays\n$forest-800: #101c14; // dark page backgrounds\n$forest-700: #17281b; // cards, hexagons, inputs\n$forest-600: #203624; // raised surfaces, chips, bars\n$forest-500: #2d4834; // hairlines and borders on dark\n$moss: #7d9b6a; // muted green, secondary text on dark\n\n// Gold — the accent, used sparingly so it stays precious\n$gold: #c9a227;\n$gold-light: #e6c65f;\n$gold-deep: #8a6d15;\n\n// Wood — warmth, rules, muted body copy\n$wood-900: #2a1d13;\n$wood-700: #4a3524;\n$wood-500: #6b4f36;\n$wood-300: #a08258;\n\n// Parchment — light surfaces, in place of white\n$parchment: #f5efe2;\n$parchment-dim: #eae1cd;\n$parchment-line: #ddd0b4;\n\n//\n// Semantic aliases — everything downstream refers to these\n//\n$primary-color: $gold;\n$light-dark: $forest-700;\n$light: #fbf7ec; // warm white for text and rules on dark\n$text-color: #6f5c44; // body copy on parchment\n$title-color: #1d2f21; // headings on parchment\n$border-color: $parchment-line;\n\n//\n// Hexagon\n//\n$sqrt3: 1.7320508075688772;\n$edgeSize: 100px;\n$hexWidth: $edgeSize * 2;\n$hexHeight: $sqrt3 * $edgeSize;\n\n// Display\n$borderHover: 15px;\n\n// Easing\n$ease-out-expo: cubic-bezier(0.19, 1, 0.22, 1);\n$ease-out-quart: cubic-bezier(0.165, 0.84, 0.44, 1);\n",".dark {\n  background-color: #101c14;\n}\n.dark .page-home .overlay {\n  background-color: rgba(11, 20, 16, 0.97);\n}\n.dark .page-title h2 {\n  color: #fbf7ec;\n}\n.dark .page-title .title-bg {\n  color: rgba(125, 155, 106, 0.06);\n}\n.dark .section-title h3::before {\n  background-color: #fbf7ec;\n}\n.dark h1,\n.dark h2,\n.dark h3,\n.dark h4,\n.dark h5,\n.dark h6,\n.dark .about-author .author-desc p {\n  color: #fbf7ec;\n}\n.dark .switcher-body h4 {\n  color: #101c14;\n}\n.dark .service-hex .st0 {\n  fill: transparent;\n}\n.dark .service-hex:hover .st0 {\n  fill: #fbf7ec;\n}\n.dark .testimonials .text,\n.dark .btn-border {\n  border-color: #17281b;\n}"]}